// WEBGIS_TESIS_TEGA — navigasi + peta latar belakang + metode

function goToSection(id) {
  const target = document.getElementById(id);
  if (!target) return;
  const nav = document.getElementById("menu-tesis");
  const offset = nav ? nav.offsetHeight : 0;
  const y = target.getBoundingClientRect().top + window.scrollY - offset;
  window.scrollTo({ top: y, behavior: "smooth" });
}

function initNavigation() {
  document.getElementById("exploreBtn")?.addEventListener("click", () => {
    goToSection("latar-belakang");
  });

  document.querySelectorAll(".nav-link[data-target]").forEach(btn => {
    btn.addEventListener("click", () => goToSection(btn.dataset.target));
  });

  const sections = [...document.querySelectorAll("main section[id]")];
  const links = [...document.querySelectorAll(".nav-link")];

  const observer = new IntersectionObserver(entries => {
    const current = entries
      .filter(e => e.isIntersecting)
      .sort((a,b) => b.intersectionRatio - a.intersectionRatio)[0];

    if (!current) return;
    links.forEach(link => {
      link.classList.toggle("active", link.dataset.target === current.target.id);
    });
  }, { rootMargin: "-35% 0px -50% 0px", threshold: [0.05, .25, .5] });

  sections.forEach(section => observer.observe(section));
}

function initMethod() {
  const steps = document.querySelectorAll(".method-step");
  const details = document.querySelectorAll(".method-detail");

  steps.forEach(step => {
    step.addEventListener("click", () => {
      steps.forEach(x => x.classList.remove("active"));
      details.forEach(x => x.classList.remove("show"));

      step.classList.add("active");
      document.getElementById(step.dataset.method)?.classList.add("show");
    });
  });
}

function initStoryMap() {
  const container = document.getElementById("storyMap");
  if (!container || typeof maplibregl === "undefined") return;

  const map = new maplibregl.Map({
    container: "storyMap",
    style: {
      version: 8,
      sources: {
        osm: {
          type: "raster",
          tiles: ["https://tile.openstreetmap.org/{z}/{x}/{y}.png"],
          tileSize: 256,
          attribution: "© OpenStreetMap contributors"
        }
      },
      layers: [{ id: "osm", type: "raster", source: "osm" }]
    },
    center: [109.13, -6.87],
    zoom: 11
  });

  map.addControl(new maplibregl.NavigationControl(), "top-right");

  map.on("load", async () => {
    try {
      // Opsional: simpan BATAS_TEGAL.geojson di folder Data/
      const response = await fetch("Data/BATAS_TEGAL.geojson");
      if (!response.ok) return;

      const data = await response.json();
      map.addSource("batas-tegal", { type: "geojson", data });

      map.addLayer({
        id: "batas-fill",
        type: "fill",
        source: "batas-tegal",
        paint: { "fill-color": "#177f7b", "fill-opacity": 0.15 }
      });

      map.addLayer({
        id: "batas-line",
        type: "line",
        source: "batas-tegal",
        paint: { "line-color": "#123746", "line-width": 2.5 }
      });

      const bounds = new maplibregl.LngLatBounds();

      function extend(coords) {
        if (!Array.isArray(coords)) return;
        if (typeof coords[0] === "number" && typeof coords[1] === "number") {
          bounds.extend(coords);
        } else {
          coords.forEach(extend);
        }
      }

      (data.features || []).forEach(f => extend(f.geometry?.coordinates));

      if (!bounds.isEmpty()) {
        map.fitBounds(bounds, { padding: 35, maxZoom: 12.5 });
      }
    } catch (err) {
      console.info("Peta dasar tetap aktif. BATAS_TEGAL.geojson belum tersedia.");
    }
  });
}

document.addEventListener("DOMContentLoaded", () => {
  initNavigation();
  initMethod();
  initStoryMap();
});


function initResultsMenu(){
  const wrap=document.querySelector('.nav-dropdown'), btn=document.getElementById('hasilMenuBtn');
  btn?.addEventListener('click',e=>{e.stopPropagation();wrap?.classList.toggle('open')});
  document.querySelectorAll('#hasilSubmenu button[data-target]').forEach(x=>x.addEventListener('click',()=>{wrap?.classList.remove('open');goToSection(x.dataset.target)}));
  document.addEventListener('click',()=>wrap?.classList.remove('open'));
}
const GEOM_BY_TRANSECT={};
function transectKey(p={}){
  const fields=['NAMA_TITIK','TRANSECT','Transect','TRANSEK','Transek','ID_TRANSEK','ID','id','NAMA'];
  for(const k of fields){if(p[k]!=null&&String(p[k]).trim()!=='')return String(p[k]).trim().toUpperCase();}
  return '';
}
function getGeomTipologi(p={}){
  const fields=['TIPOLOGI','Tipologi','tipologi','TIPOLOGI_1','TIPOLOGI_G','GEOM','Geom','geom','GEOMORFOLOGI','Geomorfologi','geomorfologi','GEOMORFOLO','JENIS_GEOM','JENIS_GEOMORFOLOGI','TIPOLOGI_GEOM','NAMA_GEOM'];
  for(const k of fields){
    const v=p[k];
    if(v!=null&&String(v).trim()!==''&&!/^[-–—]$/.test(String(v).trim())&&!/^\d+(?:[.,]\d+)?$/.test(String(v).trim())) return String(v).replaceAll('_',' ');
  }
  for(const [k,v] of Object.entries(p||{})){
    if(/geom|tipolog/i.test(k)&&v!=null&&String(v).trim()!==''&&!/skor|score/i.test(k)&&!/^\d+(?:[.,]\d+)?$/.test(String(v).trim())) return String(v).replaceAll('_',' ');
  }
  return GEOM_BY_TRANSECT[transectKey(p)]||'—';
}
function registerGeom(features=[]){
  for(const f of features){const p=f?.properties||{},g=getGeomTipologi({...p,NAMA_TITIK:''});const key=transectKey(p);if(key&&g!=='—')GEOM_BY_TRANSECT[key]=g;}
}
async function preloadGeomLookup(){
  for(const file of ['CVI_NATURAL.geojson','CVI_BUATAN.geojson','SEDIMEN_NATURAL.geojson','SEDIMEN_BUATAN.geojson']){
    try{const r=await fetch('Data/'+file);if(r.ok){const d=await r.json();registerGeom(d.features||[]);}}catch(e){}
  }
}
const GEOM_LOOKUP_READY=preloadGeomLookup();
function tip(text){return `<mark class="tip-highlight">${text}</mark>`;}
function initDsasMap(){
  const el=document.getElementById('dsasMap'); if(!el||typeof maplibregl==='undefined') return;
  const map=new maplibregl.Map({container:'dsasMap',style:{version:8,sources:{osm:{type:'raster',tiles:['https://tile.openstreetmap.org/{z}/{x}/{y}.png'],tileSize:256,attribution:'© OpenStreetMap contributors'}},layers:[{id:'osm-dsas',type:'raster',source:'osm'}]},center:[109.13,-6.86],zoom:12});
  map.addControl(new maplibregl.NavigationControl(),'top-right');
  let data=null;
  const prop=(p,names)=>{for(const n of names){if(p[n]!=null&&p[n]!=='')return p[n]}return '—'};
  const segmentType=p=>String(prop(p,['SEGMENTASI','Segmentasi','segmentasi','SEGMEN','Segmen','segmen','JENIS_PANTAI','Jenis_Pantai','jenis_pantai','JENIS','Jenis','jenis'])).toLowerCase();
  function applyFilter(kind){if(!map.getLayer('dsas-lines'))return; map.setFilter('dsas-lines',kind==='all'?null:['in',kind,['downcase',['to-string',['coalesce',['get','SEGMENTASI'],['get','Segmentasi'],['get','segmentasi'],['get','SEGMEN'],['get','Segmen'],['get','segmen'],['get','JENIS'],['get','Jenis'],['get','jenis'],'']]]]);}
  map.on('load',async()=>{try{await GEOM_LOOKUP_READY;const r=await fetch('Data/DSAS.geojson');if(!r.ok)throw 0;data=await r.json();map.addSource('dsas',{type:'geojson',data});map.addLayer({id:'dsas-lines',type:'line',source:'dsas',paint:{'line-width':['case',['boolean',['feature-state','hover'],false],5,3],'line-color':['case',['<=',['to-number',['coalesce',['get','LRR'],['get','lrr'],0]],-2],'#ff2b17',['<',['to-number',['coalesce',['get','LRR'],['get','lrr'],0]],-1],'#ff8c00',['<=',['to-number',['coalesce',['get','LRR'],['get','lrr'],0]],1],'#ffd400',['<=',['to-number',['coalesce',['get','LRR'],['get','lrr'],0]],2],'#39d400','#006cff']}});const b=new maplibregl.LngLatBounds();const ext=c=>Array.isArray(c)&&(typeof c[0]==='number'?b.extend(c):c.forEach(ext));(data.features||[]).forEach(f=>ext(f.geometry?.coordinates));if(!b.isEmpty())map.fitBounds(b,{padding:45,maxZoom:14});map.on('click','dsas-lines',e=>{const p=e.features[0].properties||{};document.getElementById('dsasInfo').innerHTML=`<span>INFORMASI SEGMEN</span><strong>${prop(p,['NAMA_TITIK','TRANSECT','Transect','ID','id'])}</strong><p>Segmentasi: <b>${prop(p,['SEGMENTASI','Segmentasi','segmentasi','SEGMEN','Segmen','segmen','JENIS_PANTAI','Jenis_Pantai','jenis_pantai'])}</b><br>Tipologi: <b>${getGeomTipologi(p)}</b><br>LRR: <b>${prop(p,['LRR','lrr'])}</b> m/tahun · EPR: <b>${prop(p,['EPR','epr'])}</b><br>NSM: <b>${prop(p,['NSM','nsm'])}</b> · SCE: <b>${prop(p,['SCE','sce'])}</b></p>`});map.on('mouseenter','dsas-lines',()=>map.getCanvas().style.cursor='pointer');map.on('mouseleave','dsas-lines',()=>map.getCanvas().style.cursor='');}catch(e){document.getElementById('dsasInfo').innerHTML='<span>DATA DSAS</span><strong>Data/DSAS.geojson belum ditemukan</strong><p>Simpan file GeoJSON Anda dengan nama <b>DSAS.geojson</b> di dalam folder <b>Data</b>. Peta akan memuatnya otomatis.</p>'}});
  function updateLegend(kind){
    const legend=document.querySelector('.dsas-legend');
    if(!legend) return;
    const prefix=kind==='natural'?'Natural':kind==='buatan'?'Buatan':'';
    const item=(cls,label)=>`<span><i class="ln ${cls}"></i>${prefix?prefix+' · ':''}${label}</span>`;
    legend.innerHTML=[
      item('abr-high','Abrasi Tinggi'),
      item('abr-mod','Abrasi Sedang'),
      item('stable','Stabil'),
      item('acc-mod','Akresi Sedang'),
      item('acc-high','Akresi Tinggi')
    ].join('');
  }
  function updateSummary(kind){
    const summaries={
      all:{lrr:'−0,96 m/tahun',pattern:'69,57% Abrasi',sub:'32 dari 46 transek',lrrText:'Tren garis pantai mundur.',patternText:'Abrasi mendominasi.',quick:'Secara keseluruhan garis pantai Kota Tegal cenderung mundur; 69,57% transek mengalami abrasi. Perbedaan respons berkaitan dengan segmentasi natural–buatan dan tipologi geomorfologi pantai.'},
      natural:{lrr:'−2,38 m/tahun',pattern:'92,3% Abrasi',sub:'12 dari 13 transek',lrrText:'Kemunduran lebih kuat.',patternText:'Abrasi sangat dominan.',quick:'Segmen natural didominasi abrasi (LRR −2,38 m/tahun; 12 dari 13 transek). Menurut tipologi geomorfologi, Pasir Halus menunjukkan kemunduran paling konsisten dengan LRR rata-rata −2,92 m/tahun, diikuti Tambak −2,00 m/tahun; Aluvial lebih bervariasi karena T44 −2,33 m/tahun sedangkan T51 +0,72 m/tahun.'},
      buatan:{lrr:'−0,38 m/tahun',pattern:'60,6% Abrasi',sub:'20 dari 33 transek',lrrText:'Kemunduran lebih rendah.',patternText:'Abrasi tetap dominan.',quick:'Segmen buatan tetap cenderung mundur (LRR −0,38 m/tahun; 20 dari 33 transek abrasi), tetapi responsnya lebih heterogen. Menurut tipologi, Tambak memiliki LRR rata-rata −1,17 m/tahun, Pasir Halus −0,84, Pasir Kasar −0,48, sedangkan Bebatuan +0,24 dan Aluvial +0,91 m/tahun.'}
    };
    const d=summaries[kind]||summaries.all;
    const set=(id,value)=>{const el=document.getElementById(id);if(el)el.textContent=value};
    set('dsasLrrValue',d.lrr);
    set('dsasPatternValue',d.pattern);
    set('dsasPatternSub',d.sub);
    set('dsasLrrConclusion',d.lrrText);
    set('dsasPatternConclusion',d.patternText);
    const qc=document.getElementById('dsasQuickConclusion'); if(qc){ const q={all:'Garis pantai Kota Tegal didominasi abrasi. Respons berbeda antara segmen natural dan buatan serta mengikuti tipologi geomorfologi.',natural:`Natural didominasi abrasi. ${tip('Pasir Halus')} menunjukkan kemunduran paling konsisten (−2,92 m/tahun), diikuti ${tip('Tambak')} (−2,00 m/tahun), sedangkan ${tip('Aluvial')} lebih bervariasi.`,buatan:`Buatan tetap didominasi abrasi tetapi lebih heterogen. ${tip('Tambak')} dan ${tip('Pasir Halus')} cenderung mundur; ${tip('Bebatuan')} dan ${tip('Aluvial')} menunjukkan kecenderungan lebih stabil/maju.`}; qc.innerHTML=q[kind]||q.all; }
  }
  function updateDiscussion(kind){
    const cards=document.querySelectorAll('[data-discussion-segment]');
    cards.forEach(card=>{
      const type=card.dataset.discussionSegment;
      card.classList.toggle('segment-hidden',kind!=='all' && type!==kind);
    });
    const note=document.querySelector('.discussion-note span');
    if(note){
      note.textContent=kind==='natural'
        ? 'Pembahasan difokuskan pada pola abrasi–akresi dan respons fisik segmen natural.'
        : kind==='buatan'
          ? 'Pembahasan difokuskan pada perubahan garis pantai pada segmen yang mengalami intervensi/struktur buatan.'
          : 'Distribusi abrasi–akresi → perbedaan natural–buatan → lokasi perubahan dominan → keterkaitan dengan analisis CVI berikutnya.';
    }
  }
  document.querySelectorAll('.segment-filter button').forEach(b=>b.addEventListener('click',()=>{
    document.querySelectorAll('.segment-filter button').forEach(x=>x.classList.remove('active'));
    b.classList.add('active');
    const kind=b.dataset.segment;
    applyFilter(kind);
    updateLegend(kind);
    updateDiscussion(kind);
    updateSummary(kind);
    const info=document.getElementById('dsasInfo');
    if(info){
      const label=kind==='natural'?'Natural':kind==='buatan'?'Buatan':'Semua Segmen';
      info.innerHTML=`<span>INFORMASI SEGMEN</span><strong>${label}</strong><p>`;
    }
  }));
}
